'use client'
/** Music: the MATRIX card `music`. Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { henryBoard } from '@/lib/matrix/widgets/boards/henry'

const preset = henryBoard.find(p => p.id === 'music')!

export type MatrixMusicProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixMusic(props: MatrixMusicProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
